import{_ as l,a0 as o,w as r,s as p,ao as d,I as n,x as s,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"使用命令列生成高強度密碼 | LCTT x X-CMD","titleTemplate":false,"description":"使用命令列生成高強度密碼 | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用命令列生成高強度密碼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用命令列生成高強度密碼 | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/20161102 Generate a strong password from the command line","title":"使用命令列生成高強度密碼","tag":"201611","desc":""},"relativePath":"201611/20161102 Generate a strong password from the command line.md","filePath":"[post].md"}'),h={name:"201611/20161102 Generate a strong password from the command line.md"};function g(c,e,m,u,b,k){const a=o("Link");return r(),p("div",null,[e[13]||(e[13]=d(`<h1 id="使用命令列生成高強度密碼" tabindex="-1">使用命令列生成高強度密碼 <a class="header-anchor" href="#使用命令列生成高強度密碼" aria-label="Permalink to “使用命令列生成高強度密碼”">​</a></h1><p><img src="https://www.rosehosting.com/blog/wp-content/uploads/2016/10/generate-a-strong-password-from-the-command-line.jpg" alt="generate-a-strong-password-from-the-command-line"></p><p>設置一個高強度的密碼是非常重要的，這樣才能夠很好的保護自己的賬號或者服務器以及確保自己的數據的安全。通常來説，一個高強度密碼至少有 14 個字符，包括大小寫字母、數字和特殊字符，並且要牢記永遠不用那些字典中的單詞。使用長密碼比短密碼要來的安全，因為密碼越長越難猜測。在本文中，我將給你介紹幾個不同方法，讓你可以在 Linux 命令列下生成一個高強度密碼。</p><h3 id="使用-openssl-生成高強度密碼" tabindex="-1">使用 openssl 生成高強度密碼 <a class="header-anchor" href="#使用-openssl-生成高強度密碼" aria-label="Permalink to “使用 openssl 生成高強度密碼”">​</a></h3><p>這裏使用 openssl 的 rand 方法，它會生成一個 14 位字符的隨機字符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>openssl rand -base64 14</span></span></code></pre></div><h3 id="使用-urandom-生成高強度密碼" tabindex="-1">使用 urandom 生成高強度密碼 <a class="header-anchor" href="#使用-urandom-生成高強度密碼" aria-label="Permalink to “使用 urandom 生成高強度密碼”">​</a></h3><p>這裏我們將使用 <code>tr</code> 條件來過濾 <code>/dev/urandom</code> 的輸出，從而刪掉那些不想要的字符，並打印出第一個出現的 14 位字符。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt; /dev/urandom tr -dc A-Za-z0-9 | head -c14; echo</span></span></code></pre></div><h3 id="使用-pwgen-生成高強度密碼" tabindex="-1">使用 pwgen 生成高強度密碼 <a class="header-anchor" href="#使用-pwgen-生成高強度密碼" aria-label="Permalink to “使用 pwgen 生成高強度密碼”">​</a></h3><p><code>pwgen</code> 是一個生成隨機、無特殊含義但可以正常拼讀的密碼。</p><p>安裝 <code>pwgen</code>，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install pwgen</span></span></code></pre></div><p>安裝好之後，使用以下命令來生成一個 14 位隨機字符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pwgen 14 1</span></span></code></pre></div><p>你也可以使用以下標記：</p><ul><li>-c 或 --capitalize 生成的密碼中至少包含一個大寫字母</li><li>-A 或 --no-capitalize 生成的密碼中不含大寫字母</li><li>-n 或 --numerals 生成的密碼中至少包含一個數字</li><li>-0 或 --no-numerals 生成的密碼中不含數字</li><li>-y 或 --symbols 生成的密碼中至少包含一個特殊字符</li><li>-s 或 --secure 生成一個完全隨機的密碼</li><li>-B 或 --ambiguous 生成的密碼中不含易混淆字符 (ambiguous characters)</li><li>-h 或 --help 輸出幫助信息</li><li>-H 或 --sha1=path/to/file[#seed] 使用指定文件的 sha1 哈希值作為隨機生成器</li><li>-C 按列輸出生成的密碼</li><li>-1 不按列輸出生成的密碼</li><li>-v 或 --no-vowels 不使用任何元音，以免意外生成讓人討厭的單詞</li></ul><h3 id="使用-gpg-生成高強度密碼" tabindex="-1">使用 gpg 生成高強度密碼 <a class="header-anchor" href="#使用-gpg-生成高強度密碼" aria-label="Permalink to “使用 gpg 生成高強度密碼”">​</a></h3><p>我們也可以使用 <code>gpg</code> 工具來生成一個 14 位字符的密碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gpg --gen-random --armor 1 14</span></span></code></pre></div><h3 id="其它方法" tabindex="-1">其它方法 <a class="header-anchor" href="#其它方法" aria-label="Permalink to “其它方法”">​</a></h3><p>當然，可能還有很多方法可以生成一個高強度密碼。比方説，你可以添加以下 bash shell 方法到 <code>~/.bashrc</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>genpasswd() { </span></span>
<span class="line"><span>    strings /dev/urandom | grep -o &#39;[[:alnum:]]&#39; | head -n 14 | tr -d &#39;\\n&#39;; echo</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>當你想要生成一個高強度的隨機密碼時，運行 <code>genpasswd</code> 就好了。</p><hr>`,25)),n("p",null,[e[1]||(e[1]=s("via: ",-1)),i(a,{href:"https://www.rosehosting.com/blog/generate-password-linux-command-line/"},{default:t(()=>[...e[0]||(e[0]=[s("https://www.rosehosting.com/blog/generate-password-linux-command-line/",-1)])]),_:1})]),n("p",null,[e[5]||(e[5]=s("作者：",-1)),i(a,{href:"www.rosehosting.com"},{default:t(()=>[...e[2]||(e[2]=[s("RoseHosting",-1)])]),_:1}),e[6]||(e[6]=s(" 譯者：",-1)),i(a,{href:"https://github.com/GHLandy"},{default:t(()=>[...e[3]||(e[3]=[s("GHLandy",-1)])]),_:1}),e[7]||(e[7]=s(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[8]||(e[8]=[s("LCTT",-1)])]),_:1}),e[11]||(e[11]=s(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...e[9]||(e[9]=[s("Linux中國",-1)])]),_:1}),e[12]||(e[12]=s(" 榮譽推出",-1))])])}const x=l(h,[["render",g]]);export{C as __pageData,x as default};
